                if minute < 0:
                    minute += 60
                    hour -= 1
            period = 'p' if period == 'a' else 'a'
            return f"{hour}:{minute} {period}m"

        # Add error text inside parentheses
        error_texts = ["(Estimated runway)", "(Delayed)", "(Rescheduled)"]
